"""3M.1 / DB-01 one-piece drawbar alternative. Shared CAD, mesh, drawing inputs.
This is a dimensioned engineering study, not a complete or released rail coupling.
"""
from pathlib import Path
import json,math,hashlib
import cadquery as cq
import ezdxf
ROOT=Path(__file__).resolve().parent
DIST=ROOT.parent.parent
def save(n,v): (ROOT/n).write_text(json.dumps(v,indent=2)+'\n')
mass_path=ROOT.parent/'brake-selection-l2/calculations/predecessor_mass_basis.json'
c=json.loads(mass_path.read_text())['configuration'];g=9.80665
dimensions={'eye_center_distance_mm':800,'width_mm':150,'end_radius_mm':75,'thickness_mm':36,'nominal_bearing_seat_diameter_mm':90,'overall_length_mm':950}
bearing={'manufacturer':'SKF','designation':'GE 60 ES-2RS','status':'Catalog interface candidate only; not selected or availability confirmed','bore_d_mm':60,'outer_D_mm':90,'inner_width_B_mm':44,'outer_width_C_mm':36,'catalog_tilt_deg':6,'tilt_condition':'Full catalog tilt requires shaft shoulder not exceeding SKF da max and sufficient surrounding joint clearance; installed movement not verified.','catalog_dynamic_C_kN':245,'catalog_static_C0_kN':1220,'catalog_mass_kg':1.10,'source':'https://www.skf.com/binaries/pub12/Images/0901d19680154a05-06116_1-EN_tcm_12-122020.pdf','source_locator':'Printed106 / PDF108; application methods printed38–77','meaning':'Spherical PLAIN bearing ratings, not rolling-bearing L10 ratings and not allowable coupling loads. Actual oscillation, pressure/velocity, lubrication, seals, fits and surrounding articulation clearance must be checked.'}
inputs={'issue':'PF-3M1-DB01-R0','date':'2026-10-19','status':'DIMENSIONED ALTERNATIVE STUDY ONLY; NOT FOR FABRICATION','part_id':'DB-01','description':'One-piece capsule-profile steel drawbar with two nominal spherical-bearing seats','geometry':dimensions,'dimension_basis':{'90_mm_bores':'Candidate GE60ES-2RS catalog OD; nominal seats only, not a finished bore instruction.','36_mm_thickness':'Candidate bearing outer-ring width C. Bearing retention and complete joint are not yet designed.','150_mm_width':'Analyst trial leaving30mm radial edge ligament and2160mm2 nominal net area at each90mm seat. Screened below; local eye contact/fatigue remains unresolved.','800_mm_centres':'Length probe for strength/packaging comparison; not derived from a selected car gap or curve and not an accepted coupling length.','end_radii':'Capsule half-width; no arbitrary sharp shoulder transition.'},'load_probe_N':200000,'load_probe_status':'Independent analyst part-load probe, not accepted design/proof load or a certified coupling capacity. Quasi-static train-force sensitivities are not impact-load limits.','material_candidate':'ASTM A572 Grade50 mill plate; current SSAB product evidence, actual plate and toughness requirements unaccepted','material_min_yield_MPa':50*6.894757293168,'material_min_tensile_MPa':65*6.894757293168,'elastic_modulus_trial_MPa':200000,'density_trial_kg_m3':7850,'bearing_candidate':bearing,'critical_dimensions_not_assigned':{'finished_bore_fit':None,'bore_roundness_cylindricity':None,'bore_position_parallelism':None,'surface_finishes':None,'edge_breaks_and_notch_acceptance':None,'bearing_axial_retention':None,'pin_material_diameter_fit_and_retention':None,'clevis_dimensions_material_joints':None,'frame_attachment_and_draft_gear':None,'full_yaw_pitch_roll_envelope':None,'fatigue_spectrum_and_allowables':None,'final_coupling_length_and_gap':None,'manufacturing_tolerances':None,'inspection_NDT_acceptance':None},'drawing_complete_for_fabrication':False,'engineering_release':False,'fabrication_release':False,'limits':['No bearing internals, pins, clevises, retention plates or frame attachment geometry is invented.','The shape is an actual defined custom-part alternative, not a generic block; every view uses these parameters.','Changing the bearing retention or joint design can require changing the part dimensions.','No inter-car passenger passage is established by this component.','Use current accepted materials, fatigue/local-contact design and professional review before any manufacturing release.']}
save('design_inputs.json',inputs)
# Enumerate binary independent rail-brake states; no slack-impact dynamics.
loads=[]
for mode,masses in [('upper',[c['locomotive_and_hotel_allocation_kg']]+[c['regular_upper_design_case_kg']]*3+[c['accessible_upper_design_case_kg']]),('tare_allocation',[c['locomotive_and_hotel_allocation_kg']]+[c['regular_tare_allocation_kg']]*3+[c['accessible_tare_allocation_kg']])]:
 for mu in [.2,.35,.5]:
  for traction_mu in [0,.3,.5]:
   P=traction_mu*masses[0]*g
   for mask in range(32):
    brakes=[mu*m*g if mask&(1<<i) else 0 for i,m in enumerate(masses)]
    a=(P-sum(brakes))/sum(masses)
    for split in range(1,5):
     tail=sum(masses[split:]);btail=sum(brakes[split:]);force=tail*a+btail
     loads.append({'mass_mode':mode,'mu_brake_trial':mu,'mu_traction_trial':traction_mu,'powered_mass_assumption_kg':masses[0],'braked_vehicles_mask_loco_C1_C2_C3_CA':mask,'split_after_vehicle_index':split-1,'tail_mass_kg':tail,'traction_N':P,'acceleration_m_s2':a,'force_N_positive_tension':force})
envelopes=[]
for split in range(1,5):
 subset=[r for r in loads if r['split_after_vehicle_index']==split-1]
 envelopes.append({'joint':f'J{split}','between':['Locomotive / C1','C1 / C2','C2 / C3','C3 / accessible'][split-1],'max_tension_case':max(subset,key=lambda r:r['force_N_positive_tension']),'max_compression_case':min(subset,key=lambda r:r['force_N_positive_tension'])})
force_basis={'issue':inputs['issue'],'mass_source_sha256':hashlib.sha256(mass_path.read_bytes()).hexdigest(),'order':'Locomotive,C1 regular,C2 regular,C3 regular,accessible','grade':0,'model':'Rigid translational train, no rolling resistance, no coupling slack, no impact, independent binary brake states. Every rail-brake force is a trial mu*m*g, not a foundation-brake rating. All allocated locomotive/hotel mass is assumed powered only for this traction sensitivity. This may overstate actual powered weight.','formulas':{'train_acceleration':'a=(P-sum(B_i))/sum(m_i)','coupler_force_on_tail':'F_j=m_tail*a+sum(B_tail); positive tension, negative compression'},'excluded':['Draft-gear stiffness/damping and coupler slack','Brake pressure/stroke timing and wheelset rotational response','Actual wheel/rail friction and lateral use of adhesion','Curve angles and coupler height moments','Wheelset/axle loads and body mass distribution','Crash, derailment, snag, blocked wheels or ground interference','Locomotive peak drawbar/drive torque and fault interlocks'],'basis_status':'Sensitivity only, not a certified force envelope. No component sizes may be released solely from it.','cases':len(loads),'envelopes':envelopes}
save('train_force_basis.json',force_basis);save('train_force_cases.json',loads)
L=800;w=150;t=36;D=90;F=200000;E=200000
area=w*t;net=(w-D)*t;I=w*t**3/12
volume=(L*w+math.pi*(w/2)**2-2*math.pi*(D/2)**2)*t
calc={'load_probe_N':F,'gross_area_mm2':area,'nominal_net_area_at_seat_mm2':net,'nominal_gross_axial_stress_MPa':F/area,'nominal_net_axial_stress_MPa':F/net,'nominal_projected_bore_pressure_MPa':F/(D*t),'weak_axis_second_moment_mm4':I,'ideal_pin_pin_column_length_probe_mm':L,'radius_of_gyration_mm':math.sqrt(I/area),'slenderness_probe':L/math.sqrt(I/area),'ideal_elastic_Euler_load_N':math.pi**2*E*I/L**2,'axial_deflection_gross_prismatic_probe_mm':F*L/(E*area),'geometry_volume_mm3':volume,'mass_geometry_estimate_kg':volume*7850e-9,'interpretation':['Gross/net stresses and bore pressure are nominal section checks, not local contact/eye stresses.','Euler load is an ideal elastic column result. Inelastic behavior, eccentricity, bearing/joint flexibility and imperfections require design checks; it is not an allowable compression rating.','Fatigue, fretting, local bore/ligament stresses, out-of-plane bending, toughness and retention are not closed.','The200kN probe is not a proof-load instruction or an accepted coupling rating.','Basic spherical-plain bearing C/C0 figures are not whole-coupler load ratings.']}
save('part_calculations.json',calc)
# Exact nominal capsule and bores. CAD and mesh share the same B-rep.
r=w/2
part=(cq.Workplane('XY').moveTo(0,-r).lineTo(L,-r).threePointArc((L+r,0),(L,r)).lineTo(0,r).threePointArc((-r,0),(0,-r)).close().extrude(t/2,both=True).faces('>Z').workplane().pushPoints([(0,0),(L,0)]).hole(D))
solid=part.val();assert solid.isValid();assert len(part.solids().vals())==1
assert abs(solid.Volume()-volume)<1e-5*volume
cq.exporters.export(part,str(ROOT/'DB01_STUDY_NOT_FOR_FABRICATION.step'))
cq.exporters.export(part,str(ROOT/'DB01_STUDY_NOT_FOR_FABRICATION.stl'),tolerance=.3,angularTolerance=.1)
vertices,triangles=solid.tessellate(.3,.1)
mesh={'issue':inputs['issue'],'part_id':'DB-01','units':'mm','status':inputs['status'],'geometry_source':'design_inputs.json plus build_study.py B-rep','positions':[v for p in vertices for v in p.toTuple()],'indices':[v for f in triangles for v in f],'bounds':{'x':[-75,875],'y':[-75,75],'z':[-18,18]},'included':['Nominal one-piece bar and bearing seats'],'not_included':['Bearings','Pins and clevises','Retention','Frame attachments','Draft gear'],'geometry':dimensions}
save('DB01-mesh.json',mesh)
doc=ezdxf.new('R2010');m=doc.modelspace();doc.layers.new('STUDY_GEOMETRY_NOT_RELEASED',dxfattribs={'color':3});doc.layers.new('STATUS',dxfattribs={'color':1})
att={'layer':'STUDY_GEOMETRY_NOT_RELEASED'}
m.add_line((0,-r),(L,-r),dxfattribs=att);m.add_arc((L,0),r,270,90,dxfattribs=att);m.add_line((L,r),(0,r),dxfattribs=att);m.add_arc((0,0),r,90,270,dxfattribs=att)
for x in [0,L]:m.add_circle((x,0),D/2,dxfattribs=att)
m.add_text('DB-01 NOMINAL STUDY ONLY - NOT FOR FABRICATION OR NC CUTTING',dxfattribs={'height':12,'layer':'STATUS','insert':(-75,110)})
doc.saveas(ROOT/'DB01_NOMINAL_PROFILE_NOT_FOR_NC.dxf')
sources=[{'id':'SKF-SP','publisher':'SKF','url':bearing['source'],'checked':'2026-10-19','evidence':'Official spherical plain bearing catalog. GE60ES-2RS dimensions60/90/44/36mm, tilt6deg, catalog C245kN/C01220kN. Delivered revision, availability and application acceptance absent.'},{'id':'SSAB50','publisher':'SSAB','url':'https://www.ssab.com/en-us/brands-and-products/commercial-steel/structural-steel/astm-a572/grade-50','checked':'2026-10-19','evidence':'A572Grade50 mill-plate range4.78–102mm; minimum yield50ksi/tensile65ksi. Toughness must be specified when important. No supplier quote or actual plate acceptance.'},{'id':'DELLNER-SP','publisher':'Dellner','url':'https://www.dellner.com/products/semi-permanent-couplers','checked':'2026-10-19','evidence':'Real passenger-rail semi-permanent arrangement comparison; does not validate DB01 or supply an applicable rating.'},{'id':'IRWIN-W','publisher':'Irwin Car','url':'https://www.irwincar.com/rail-products/couplers/','checked':'2026-10-19','evidence':'Industrial Willison35990 /3/4Sharon comparison. Published vehicle-tonnage categories are not coupler tensile/compressive force ratings.'}]
save('sources.json',sources)
register={'issue':inputs['issue'],'defined_custom_part':'DB-01 nominal geometry and material alternative only','bearing_candidate':bearing,'unresolved_parts':[{'id':'DB-02','name':'Two spherical bearing units','evidence_needed':'Exact delivered designation, operating life, lubrication, fits, oscillation and installed tilt acceptance'},{'id':'DB-03','name':'Pins and primary/secondary retention','evidence_needed':'Combined shear/bending/contact/fatigue, fits, materials, replacement limits, fail-safe retention'},{'id':'DB-04','name':'Articulated frame clevises, draft gear and attachments','evidence_needed':'Tension/compression/fatigue, preload/damping/slack, curve/suspension articulation, body-frame local strength'},{'id':'DB-05','name':'Bearing axial retention and service access','evidence_needed':'Shoulders/retainers, axial and misalignment loads, fastening and full-angle clearance'},{'id':'DB-06','name':'Independent secondary restraint, guards, hose and cable supports','evidence_needed':'Separation load/energy and brake-response coordination; no generic trailer safety-chain substitution'}],'fabrication_sequence_for_review':['Accept force/duty/articulation basis and final length before freezing geometry.','Complete eye contact/fatigue, bearing retention, pin and clevis design; revise bar geometry if needed.','Obtain certified plate with accepted toughness and machining allowance; no order is authorized by this study.','Engineer/fabricator selects blank cutting and finish machining with thermal-edge cleanup requirements.','Define datum, finish, fit, NDT and inspection acceptance before releasing a traveler.','Perform first-article dimensional/material/NDT verification, guarded proof/fatigue/articulation tests under an approved program, then engineering acceptance.'],'crew_scope':'Farm crew can review access and service arrangements and build non-load-bearing cardboard/wood clearance mockups. Qualified engineering, certified safety-critical machining/fabrication and specialist inspection remain necessary.','readiness':'No production-ready part, NC release or completed coupling assembly is claimed.'}
save('part_and_release_register.json',register)
validation={'issue':inputs['issue'],'checks':['Single valid CAD solid','Analytical/CAD volume agreement','Shared B-rep for STEP/STL/web mesh','Nominal DXF uses same geometry parameters','Train-force model includes576 mass/adhesion/traction/brake cases at4joints'],'mesh_vertices':len(vertices),'mesh_triangles':len(triangles),'case_rows':len(loads),'volume_check_mm3':solid.Volume(),'fabrication_approval':False}
assert len(loads)==2304
save('validation.json',validation)
print(json.dumps({'part':dimensions,'mass_kg':calc['mass_geometry_estimate_kg'],'force_extrema_kN':[(r['joint'],r['max_tension_case']['force_N_positive_tension']/1000,r['max_compression_case']['force_N_positive_tension']/1000) for r in envelopes],'CAD_valid':solid.isValid()}))
